1	import DirtyConfirmModal from './dirty-confirm-modal';
2	import NiceModal from '@ebay/nice-modal-react';
3	import React, {useEffect, useRef} from 'react';
4	import {Button, Dialog, DialogContent, DialogTitle} from '@tryghost/shade/components';
5	import {type OkProps} from '@tryghost/admin-x-framework/hooks';
6	import {cn} from '@tryghost/shade/utils';
7	
8	interface EmailDesignModalProps {
9	    open: boolean;
10	    title: string;
11	    preview: React.ReactNode;
12	    sidebar: React.ReactNode;
13	    dirty?: boolean;
14	    isLoading?: boolean;
15	    okProps?: Pick<OkProps, 'color' | 'disabled' | 'label'>;
16	    onSave: () => void;
17	    onClose: () => void;
18	    afterClose?: () => void;
19	    testId?: string;
20	}
21	
22	const EmailDesignModal: React.FC<EmailDesignModalProps> = ({
23	    open,
24	    title,
25	    preview,
26	    sidebar,
27	    dirty = false,
28	    isLoading = false,
29	    okProps,
30	    onSave,
31	    onClose,
32	    afterClose,
33	    testId
34	}) => {
35	    const onSaveRef = useRef(onSave);
36	    const prevOpenRef = useRef(open);
37	
38	    useEffect(() => {
39	        onSaveRef.current = onSave;
40	    }, [onSave]);
41	
42	    useEffect(() => {
43	        if (prevOpenRef.current && !open) {
44	            afterClose?.();
45	        }
46	
47	        prevOpenRef.current = open;
48	    }, [afterClose, open]);
49	
50	    useEffect(() => {
51	        const handleKeyDown = (e: KeyboardEvent) => {
52	            if ((e.metaKey || e.ctrlKey) && e.key === 's') {
53	                e.preventDefault();
54	                onSaveRef.current();
55	            }
56	        };
57	        window.addEventListener('keydown', handleKeyDown);
58	        return () => window.removeEventListener('keydown', handleKeyDown);
59	    }, []);
60	
61	    const handleClose = async () => {
62	        if (!dirty) {
63	            onClose();
64	            return;
65	        }
66	
67	        const shouldLeave = await NiceModal.show(DirtyConfirmModal) as boolean;
68	        if (shouldLeave) {
69	            onClose();
70	        }
71	    };
72	
73	    return (
74	        <Dialog
75	            open={open}
76	            onOpenChange={(isOpen) => {
77	                if (!isOpen) {
78	                    handleClose();
79	                }
80	            }}
81	        >
82	            <DialogContent
83	                className={cn(
84	                    'top-[50%] left-[50%] h-[calc(100vh-8vmin)] w-[calc(100vw-8vmin)] max-w-none translate-x-[-50%] translate-y-[-50%] gap-0 overflow-hidden p-0'
85	                )}
86	                data-testid={testId}
87	                onEscapeKeyDown={(event) => {
88	                    event.preventDefault();
89	                    event.stopPropagation();
90	                    handleClose();
91	                }}
92	            >
93	                <div className="flex h-full min-h-0">
94	                    <div className="hidden min-h-0 flex-1 flex-col bg-gray-50 dark:bg-black [@media(min-width:801px)]:flex">
95	                        <div className="flex min-h-0 flex-1 items-center justify-center p-8">
96	                            {preview}
97	                        </div>
98	                    </div>
99	
100	                    <div className="flex min-h-0 w-full flex-col border-l border-gray-200 dark:border-gray-900 [@media(min-width:801px)]:w-[400px] [@media(min-width:801px)]:shrink-0">
101	                        <div className="flex items-center justify-between px-6 py-5">
102	                            <DialogTitle>{title}</DialogTitle>
103	                            <div className="flex items-center gap-2">
104	                                <Button variant="outline" onClick={() => handleClose()}>Close</Button>
105	                                <Button
106	                                    className={okProps?.color === 'green' ? 'bg-green text-white hover:bg-green/90' : undefined}
107	                                    disabled={isLoading || okProps?.disabled}
108	                                    variant={okProps?.color === 'red' ? 'destructive' : 'default'}
109	                                    onClick={onSave}
110	                                >
111	                                    {okProps?.label || 'Save'}
112	                                </Button>
113	                            </div>
114	                        </div>
115	                        {sidebar}
116	                    </div>
117	                </div>
118	            </DialogContent>
119	        </Dialog>
120	    );
121	};
122	
123	export default EmailDesignModal;
124

