34	        renderField(<ButtonColorField />, {...DEFAULT_EMAIL_DESIGN, button_color: 'accent'});
35	
36	        const trigger = screen.getByRole('button', {name: 'Pick color'});
37	        const swatch = trigger.querySelector(String.raw`.inset-\[3px\]`);
38	
39	        assert.ok(swatch);
40	        assert.equal(swatch.getAttribute('style')?.includes('rgb(255, 0, 136)'), true);
41	    });
42	
43	    it('renders accent-backed link colors using the resolved accent color', function () {
44	        renderField(<LinkColorField />, {...DEFAULT_EMAIL_DESIGN, link_color: 'accent'}, '#00aaee');
45	
46	        const trigger = screen.getByRole('button', {name: 'Pick color'});
47	        const swatch = trigger.querySelector(String.raw`.inset-\[3px\]`);
48	
49	        assert.ok(swatch);
50	        assert.equal(swatch.getAttribute('style')?.includes('rgb(0, 170, 238)'), true);
51	    });
52	
53	    it('shows semantic swatches for each configured welcome-email color field', function () {
54	        const background = renderField(<BackgroundColorField />);
55	        openPicker('Background color');
56	        assert.ok(screen.getByRole('button', {name: 'White'}));
57	        background.unmount();
58	
59	        const header = renderField(<HeaderBackgroundField />);
60	        openPicker('Header background color');
61	        const transparentSwatch = screen.getByRole('button', {name: 'Transparent'});
62	        const pickerTrigger = screen.getByRole('button', {name: 'Pick color'});
