import type {EmailDesignSettings} from './types';

interface EmailDesignContextValue {
    settings: EmailDesignSettings;
    onSettingsChange: (updates: Partial<EmailDesignSettings>) => void;
    accentColor: string;
    /**
     * Registers a color picker as open (or in the process of opening) and returns
     * an unregister callback. Used so the modal can intercept the Escape key while a
     * color picker is open — even before its popover content has finished mounting.
     */
    registerColorPicker: (close: () => void) => () => void;
    /** True while at least one color picker is open or opening. */
    hasOpenColorPickers: () => boolean;
    /** Closes any open/opening color pickers. */
    closeColorPickers: () => void;
}

const EmailDesignContext = createContext<EmailDesignContextValue | undefined>(undefined);

interface EmailDesignProviderProps {
    settings: EmailDesignSettings;
    onSettingsChange: (updates: Partial<EmailDesignSettings>) => void;
    accentColor: string;
    children: ReactNode;
}

export const EmailDesignProvider = ({settings, onSettingsChange, accentColor, children}: EmailDesignProviderProps) => {
    const openColorPickers = useRef(new Map<number, () => void>());
    const nextColorPickerId = useRef(0);

    const registerColorPicker = useCallback((close: () => void) => {
        const id = nextColorPickerId.current++;
        openColorPickers.current.set(id, close);
        return () => {
            openColorPickers.current.delete(id);
        };
    }, []);

    const hasOpenColorPickers = useCallback(() => openColorPickers.current.size > 0, []);

    const closeColorPickers = useCallback(() => {
        openColorPickers.current.forEach(close => close());
        openColorPickers.current.clear();
    }, []);

    const value = useMemo<EmailDesignContextValue>(() => ({
        settings,
        onSettingsChange,
        accentColor,
        registerColorPicker,
        hasOpenColorPickers,
        closeColorPickers
    }), [settings, onSettingsChange, accentColor, registerColorPicker, hasOpenColorPickers, closeColorPickers]);

    return (
        <EmailDesignContext.Provider value={value}>
            {children}
        </EmailDesignContext.Provider>
    );
};

export const useEmailDesign = (): EmailDesignContextValue => {
    const ctx = useContext(EmailDesignContext);
    if (!ctx) {
        throw new Error('useEmailDesign must be used within an EmailDesignProvider');
    }
    return ctx;
};
