describe('scratch escape', function () {
    it('keeps modal open when Escape pressed after popover mounts', async function () {
        let closed = false;
        renderModal(() => {
            closed = true;
        });
        await act(async () => {
            fireEvent.click(screen.getByText('Button color'));
            await new Promise(r => setTimeout(r, 0));
        });
        // popover mounted
        assert.ok(screen.getByRole('textbox'));
        await act(async () => {
            fireEvent.keyDown(document.body, {key: 'Escape', code: 'Escape'});
            await new Promise(r => setTimeout(r, 0));
        });
        assert.equal(closed, false, 'onClose must not be called');
        assert.ok(screen.getByTestId('email-design-modal'), 'modal must remain');
    });

    it('keeps modal open when Escape pressed immediately after opening (before mount)', async function () {
        let closed = false;
        renderModal(() => {
            closed = true;
        });
        act(() => {
            fireEvent.click(screen.getByText('Button color'));
            fireEvent.keyDown(document.body, {key: 'Escape', code: 'Escape'});
        });
        await act(async () => {
            await new Promise(r => setTimeout(r, 0));
        });
        assert.equal(closed, false, 'onClose must not be called');
        assert.ok(screen.getByTestId('email-design-modal'), 'modal must remain');
    });
});
